from pathlib import Path
from html import escape
from design import LEVEL,DEPTH,DATA,calc
from page import titles,intro,program,obstacles,light,reg,sources

D=Path(__file__).resolve().parent;out=D.parent/'due-camere'
def it(v):return f'{v:.2f}'.replace('.',',')
def image(file,caption,klass=''):
    return f'<figure class="{klass}"><img src="{(out/file).as_uri()}"><figcaption>{escape(caption)}</figcaption></figure>'
def p(title,body):return f'<article><h3>{title}</h3><p>{body}</p></article>'
def table(columns,rows):
    return '<table><tr>'+''.join(f'<th>{c}</th>' for c in columns)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row)+'</tr>' for row in rows)+'</table>'
pages=[]
def add(code,title,sub,body):
    pages.append(f'<section><header><b>ARCHAI / CASATATOTATA</b><span>PALAZZO LOMBARDO · PIAZZA REGINA MARGHERITA 22</span><b>{code}</b></header><h1>{title}</h1><p class="sub">{sub}</p>{body}<footer><span>STUDIO PRELIMINARE · DUE CAMERE IN QUOTA · R05</span><b>{len(pages)+1:02}</b></footer></section>')
add('Confronto','Due singole al piano alto','Una camera sulla piazza e una sul retro. Due scale indipendenti, letti 90 × 200 cm, sbarco escluso dal netto e guardaroba nel vano a cuneo.', '<div class="two">'+image('L-piazza.webp','Camera sulla piazza · spaccato della variante L.')+image('L-retro.webp','Camera sul retro · spaccato della variante L.')+'</div>'+table(['Sezione','Sopra a H = 4,20','Sotto','Uso al piano principale','Valutazione'],[['F · +2,92 m','1,28 m','2,70 m','Rimane una matrimoniale sotto la singola anteriore','Scartare l’uso abituale alla quota documentata.'],['L · +1,08 m','3,12 m','0,90 m','Due basamenti chiusi sostituiscono il pavimento abitabile occupato','Verificare per prima se si accettano due singole e si risolvono luce e titoli.']]))
for v in 'FL':
    r=DATA[v]
    add(v+' / piante',titles[v],intro[v],'<div class="two plans">'+image(v+'-L0.svg','L0 · Piano principale, proiezione delle camere superiori e rampe.')+image(v+'-L1.svg','L1 · Piano delle camere; lo sbarco si trova fuori dal loro perimetro netto.')+'</div>'+p('Distribuzione',program[v])+p('Varchi e passaggi',obstacles[v]))
    rows=[]
    for k,name in [('piazza','Sulla piazza'),('retro','Sul retro')]:
        m=calc(r[k]);x,y,X,Y=r[k]['deck'];rows.append([name,it(X-x-.16)+' × '+it(Y-y-.16)+' m',it(m['net'])+' m²',it(m['area'])+' m²',it(m['ramp'])+' m²',it(m['landing'])+' m²',it(m['turn'])+' m²'])
    add(v+' / camere','Le due camere e gli sbarchi','Netto di progetto dopo una riserva di 8 cm per lato; misure su traccia catastale, con posizione dei divisori ancora da rilevare.', '<div class="two">'+image(v+'-piazza.webp','Camera sulla piazza · passaggio separato dal letto.')+image(v+'-retro.webp','Camera sul retro · scala sul lato della cucina.')+'</div>'+table(['Camera','Rettangolo netto','Netto stanza','Impalcato lordo','Proiezione rampe','Sbarco alto','Ripiano intermedio'],rows)+p('Come leggere le superfici','Le camere sono singole. I 9 m² sono un riferimento ordinario per una persona, i 14 m² per due. Sul fronte il margine è minimo: un rilievo o una controparete più spessa possono far scendere il netto sotto il riferimento.'))
    add(v+' / sezioni','Quanto resta sopra e sotto','Le linee a 4,20 m restituiscono la media DOCFA. Non rappresentano una sezione misurata della volta.', '<div class="two sections">'+image(v+'-sezione-piazza.svg','Scala sul fronte. In F il ripiano intermedio collega due rampe perpendicolari.')+image(v+'-sezione.svg','Scala diritta sul retro. La sezione sviluppata disegna l’impalcato in proiezione.')+'</div><div class="two">'+p('Altezza richiesta',('Per avere 2,70 m utili sopra e sotto, con 22 cm di struttura, servono 5,62 m locali. Rispetto a 4,20 m mancano 1,42 m. Neppure una punta alta della volta garantisce l’altezza necessaria su letti, porte e rampe.' if v=='F' else 'Per avere 2,70 m sopra il pavimento rialzato occorrono 3,78 m locali. Dove la volta fosse a 4,20 m, rimarrebbero 42 cm di margine. Sotto il piano restano 90 cm per contenimento.'))+p('Accesso',obstacles[v])+'</div>')
add('Verifica','Prima di attribuire valore alle camere','Il test geometrico distingue due letti che entrano in pianta da due camere effettivamente assentibili.', '<div class="two"><div>'+p('Aperture',light)+p('Impalcati e incidenza','Il vano frontale misura circa 20,8 m² e un terzo vale 6,93 m². Il solo impalcato F occupa 10,06 m². Sul retro, 39,9 m² per l’intero salone danno 13,30 m²; impalcato F, rampa e sbarco occupano in proiezione circa 15,04 m². Contare la sola campata riduce ancora il denominatore. Il Comune deve chiarire criterio e norma applicabili.')+p('Soppalco e base chiusa',reg)+'</div><div>'+p('Rilievo da richiedere','Riportare sulla stessa tavola le due diagonali, le quote finite del pavimento, l’intradosso in una maglia fitta, ogni gradino, i punti di imposta e chiave. Misurare le luci nette apribili. Chiedere accesso agli atti, verifica del fabbricato storico, carichi, fondazioni, appoggi, requisiti di sicurezza e accessibilità. Eventuali nuove aperture sono un’ulteriore verifica, non un presupposto.')+p('Fonti','NCV364 · pp. 4 e 11 per appartamento e altezza media. Per i riscontri fotografici e le fonti di agenzia si rimanda al dossier pubblico R04. ' + ' · '.join(f'<a href="{u}">{t}</a>' for t,u in sources))+p('File modificabili','Nello ZIP si trovano le scene native Blender, i GLB, lo scambio IFC con due spazi-camera e le piante e sezioni DXF espresse in metri. I render interni F guardano da una quota bassa per rendere percepibile il conflitto con il soffitto.')+'</div></div>')
css="""@page{size:A3 landscape;margin:0}*{box-sizing:border-box}body{margin:0;color:#283c2e;font:17px/1.4 Arial,sans-serif;background:#f8f5ea;-webkit-print-color-adjust:exact;print-color-adjust:exact}section{width:420mm;height:296.8mm;overflow:hidden;position:relative;break-after:page;padding:12mm 14mm 14mm}section:last-child{break-after:auto}header,footer{display:flex;justify-content:space-between;border-bottom:1px solid #b1bbab;letter-spacing:1px;font-size:12px;padding-bottom:3mm}footer{position:absolute;left:14mm;right:14mm;bottom:5mm;border-top:1px solid #b1bbab;border-bottom:0;padding-top:2mm}h1,h3{font-family:Georgia,serif;font-weight:400;line-height:1.08}h1{font-size:52px;letter-spacing:-2px;margin:5mm 0 2mm}.sub{font:22px/1.3 Georgia,serif;margin:0 0 5mm;color:#576752}.two{display:grid;grid-template-columns:1fr 1fr;gap:7mm;align-items:start}figure{margin:0}figure img{width:100%;height:116mm;object-fit:contain;display:block;background:#e7e5d9}.plans figure img{height:142mm}.sections figure img{height:115mm}figcaption{margin:2mm 0 3mm;color:#546552;font-size:14px}table{width:100%;border-collapse:collapse;margin:3mm 0}td,th{text-align:left;padding:2.4mm;vertical-align:top;border-bottom:1px solid #b4beb0}th{background:#2e503e;color:#fff}p{margin:0}article{border-top:1px solid #b8c1b2;padding:2.5mm 0 2mm}h3{font-size:23px;margin:0 0 1.5mm}a{color:#815338}"""
(D/'book.html').write_text('<!doctype html><meta charset="utf-8"><style>'+css+'</style>'+''.join(pages),encoding='utf8')
